(function(root){'use strict';
 const source=document.currentScript?.src||location.href;
 const encoded='';
 function bytes(){const binary=atob(encoded),value=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)value[i]=binary.charCodeAt(i);return value;}
 async function plain(){const response=await fetch(new URL('catalog-home.json',source),{credentials:'omit',cache:'force-cache'});if(!response.ok)throw Error('目录加载失败');return response.json();}
 async function load(){try{if(!('DecompressionStream'in root))return plain();const stream=new Blob([bytes()]).stream().pipeThrough(new DecompressionStream('gzip'));const data=await new Response(stream).json();root.ToolboxCatalog=data;return data;}catch(error){console.warn('Compressed catalog fallback',error);const data=await plain();root.ToolboxCatalog=data;return data;}}
 root.ToolboxCatalogReady=load().then(data=>{root.dispatchEvent(new Event('toolbox:catalog-ready'));return data;}).catch(error=>{root.dispatchEvent(new CustomEvent('toolbox:catalog-error',{detail:error}));throw error;});
})(globalThis);
